import sys

MOD = 998244353


def factorize(x: int):
    res = {}
    d = 2
    while d * d <= x:
        while x % d == 0:
            res[d] = res.get(d, 0) + 1
            x //= d
        d += 1
    if x > 1:
        res[x] = res.get(x, 0) + 1
    return res


def prime_contribution(p: int, b, N: int) -> int:
    """
    b[i] = v_p(A_{i+1}) for i=0..N-2
    Need sum over e_1..e_N >=0:
      |e_i - e_{i+1}| = b_i, and min(e)=0
    of p^(sum e_i).
    """
    B = sum(b)
    if B == 0:
        # All differences are 0 -> all e_i equal; min(e)=0 forces all zero.
        return 1

    powp = [1] * (B + 1)
    for i in range(1, B + 1):
        powp[i] = (powp[i - 1] * p) % MOD

    # ns[h]: total weight for paths ending at height h, zero not seen yet
    # ss[h]: total weight for paths ending at height h, zero seen already
    ns = [0] * (B + 1)
    ss = [0] * (B + 1)

    # Initialize e1 = h
    ss[0] = 1  # p^0
    for h in range(1, B + 1):
        ns[h] = powp[h]

    for d in b:
        nns = [0] * (B + 1)
        nss = [0] * (B + 1)

        if d == 0:
            for h in range(B + 1):
                mul = powp[h]  # factor from new element e_{i+1}=h

                v0 = ns[h]
                if v0:
                    # If h==0, zero is seen now.
                    if h == 0:
                        nss[0] = (nss[0] + v0 * mul) % MOD
                    else:
                        nns[h] = (nns[h] + v0 * mul) % MOD

                v1 = ss[h]
                if v1:
                    nss[h] = (nss[h] + v1 * mul) % MOD
        else:
            for h in range(B + 1):
                v0 = ns[h]
                v1 = ss[h]
                if not v0 and not v1:
                    continue

                hp = h + d
                if hp <= B:
                    mul = powp[hp]
                    if v0:
                        nns[hp] = (nns[hp] + v0 * mul) % MOD
                    if v1:
                        nss[hp] = (nss[hp] + v1 * mul) % MOD

                hm = h - d
                if hm >= 0:
                    mul = powp[hm]
                    if v0:
                        if hm == 0:
                            nss[0] = (nss[0] + v0 * mul) % MOD
                        else:
                            nns[hm] = (nns[hm] + v0 * mul) % MOD
                    if v1:
                        nss[hm] = (nss[hm] + v1 * mul) % MOD

        ns, ss = nns, nss

    return sum(ss) % MOD


