    data = sys.stdin.buffer.read().split()
    if not data:
        return

    N = int(data[0])
    A = list(map(int, data[1:]))

    facs = [factorize(x) for x in A]
    primes = set()
    for f in facs:
        primes.update(f.keys())

    ans = 1
    for p in primes:
        b = [f.get(p, 0) for f in facs]
        ans = (ans * prime_contribution(p, b, N)) % MOD

    print(ans)


