                x, y = a, b
            else:
                x, y = b, a
            events[y].append((x, i))

        cnt = [0] * (n + 1)          # count of seen pairs with left endpoint x
        unique_id = [-1] * (n + 1)   # pair id when cnt[x] == 1

        top1 = 0  # largest x seen so far
        top2 = 0  # second-largest distinct x (< top1)

        base = 0
        gain = [0] * m

        for r in range(1, n + 1):
